fn span(start:usize,end:usize)->XmlSpan{XmlSpan{offset:start,length:end.saturating_sub(start)}}
fn scan_name(source:&[u8],scan:&mut NameScan,limit:usize,qname:bool)->Result<Option<NameParts>,(XmlError,usize)>{
    let mut p=scan.pos;
    while p<limit&&p<source.len(){
        let at=scan.partial_start.unwrap_or(p);
        let Some((cp,next))=utf8_next(source,at)else{return Err((XmlError::InvalidUtf8,at))};
        let first=at==scan.start;
        if !(if first{is_name_start(cp)}else{is_name_char(cp)}){
            if first{return Err((XmlError::InvalidName,at))}break
        }
        if cp==b':' as u32&&scan.partial_start.is_none(){
            if qname&&scan.first_colon.is_some(){return Err((XmlError::InvalidName,scan.first_colon.unwrap_or(at)))}
            if scan.first_colon.is_none(){scan.first_colon=Some(at)}
        }
        p=next.min(limit);scan.pos=p;
        if p-scan.start>MAX_TOKEN_NAME_BYTES{return Err((XmlError::MalformedSyntax,scan.start))}
        if p<next{scan.partial_start=Some(at);return Ok(None)}
        scan.partial_start=None;
    }
    scan.pos=p;
    if p==scan.start{return if p==source.len(){Err((XmlError::InvalidName,scan.start))}else{Ok(None)}}
    if p==limit&&p<source.len(){return Ok(None)}
    if qname&&(source.get(scan.start)==Some(&b':')||source.get(p.saturating_sub(1))==Some(&b':')){return Err((XmlError::InvalidName,scan.start))}
    let name=span(scan.start,p);let (prefix,local)=if let Some(c)=scan.first_colon{(span(scan.start,c),span(c+1,p))}else{(XmlSpan{offset:scan.start,length:0},name)};
    if qname&&scan.first_colon.is_some(){let Some((cp,_))=utf8_next(source,local.offset)else{return Err((XmlError::InvalidUtf8,local.offset))};if !is_name_start(cp){return Err((XmlError::InvalidName,local.offset))}}
    Ok(Some(NameParts{name,prefix,local}))
}

